from __future__ import annotations

from typing import List, Any, Optional, TYPE_CHECKING

from pydantic import BaseModel

if TYPE_CHECKING:
    from ...schemas.enums.EventType import EventTypeEnum


class Event(BaseModel):
    type: EventTypeEnum
    eventData: dict[str, Any]


class Data(BaseModel):
    fetchBaseURL: str
    hotstartDataComplete: Optional[bool] = True
    timeToNextFetch: int
    events: List[Event]


class Response(BaseModel):
    statusCode: int
    data: Data


class FetchEventsResponseSchema(BaseModel):
    response: Response
